root=Path(__file__).resolve().parent;reports=root/'reports';project=Path('/home/lailai/ollama-test');portal=Path('/home/lailai/slurm-portal')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(name,text):(root/name).write_text(text)
def js(name,obj):write(name,json.dumps(obj,indent=2)+'\n')
def csvwrite(name,rows):
 with (root/name).open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
