summary=[];cases=[]
for name,expected in [('portal-host',96),('chat-host',35),('postgres-host',11),('portal-characterization-host',2),('chat-characterization-host',2)]:
 command=json.loads((root/'raw'/f'{name}-command.json').read_text());assert command['exit_code']==0
 tree=ET.parse(root/'raw'/f'{name}.xml');tests=tree.findall('.//testcase');assert len(tests)==expected
