 summary.append({'suite':name,'passed':expected,'failures':0,'errors':0,'skipped':0,'exit_code':0,'junit_seconds':sum(float(t.get('time','0')) for t in tests),'log':f'raw/{name}.log','exact_command':f'raw/{name}-command.json'})
